// A tiny MCP server for tests: newline-delimited JSON-RPC over stdio, or streamable HTTP with
// `--http <port-file>` (it writes the port it listens on). It serves one prompt, one resource and
// one tool, and logs every request method to stderr so tests can see what was asked.
import { createServer } from 'node:http';
import { writeFileSync } from 'node:fs';

const PROMPT = '# Security checklist\n\n- Every entry point has an owner.\n- Secrets never live in configuration.\n';
const RESOURCE = '# {{work.id}} decision record\n\n## Context\n\n## Decision\n\n## Consequences\n\n{{inputs}}\n';

function handle(message) {
  process.stderr.write(`${message.method}\n`);
  const result = (value) => ({ jsonrpc: '2.0', id: message.id, result: value });
  switch (message.method) {
    case 'initialize': return result({ protocolVersion: message.params?.protocolVersion ?? '2025-06-18', capabilities: { prompts: {}, resources: {}, tools: {} }, serverInfo: { name: 'docs-fixture', version: '1.2.3' } });
    case 'notifications/initialized': return null;
    case 'prompts/list': return result({ prompts: [{ name: 'security-checklist', description: 'A checklist for design reviews.', arguments: [{ name: 'area', description: 'Which area', required: false }] }, { name: 'secret-prompt', description: 'Not allowed by policy.' }] });
    case 'prompts/get': {
      const area = message.params?.arguments?.area;
      if (message.params?.name !== 'security-checklist') return { jsonrpc: '2.0', id: message.id, error: { code: -32602, message: 'unknown prompt' } };
      return result({ messages: [{ role: 'user', content: { type: 'text', text: area ? `${PROMPT}\nFocus: ${area}\n` : PROMPT } }] });
    }
    case 'resources/list': return result({ resources: [{ uri: 'docs://templates/decision-record', name: 'Decision record', mimeType: 'text/markdown' }, { uri: 'docs://private/notes', name: 'Private notes' }] });
    case 'resources/read': return message.params?.uri === 'docs://templates/decision-record'
      ? result({ contents: [{ uri: message.params.uri, mimeType: 'text/markdown', text: RESOURCE }] })
      : { jsonrpc: '2.0', id: message.id, error: { code: -32002, message: 'resource not found' } };
    case 'tools/list': return result({ tools: [{ name: 'render-notes', description: 'Renders design notes.', inputSchema: { type: 'object', properties: { topic: { type: 'string', description: 'Topic' } }, required: ['topic'] } }, { name: 'fail', inputSchema: { type: 'object' } }] });
    case 'tools/call': return message.params?.name === 'fail'
      ? result({ isError: true, content: [{ type: 'text', text: 'the tool broke' }] })
      : result({ content: [{ type: 'text', text: `# Notes on ${message.params?.arguments?.topic ?? 'nothing'}\n\n- Generated by the fixture.\n` }] });
    default: return message.id == null ? null : { jsonrpc: '2.0', id: message.id, error: { code: -32601, message: 'method not found' } };
  }
}

const httpIndex = process.argv.indexOf('--http');
if (httpIndex >= 0) {
  const portFile = process.argv[httpIndex + 1];
  const streaming = process.argv.includes('--sse');
  const server = createServer((request, response) => {
    if (request.method === 'DELETE') { response.writeHead(204).end(); return; }
    let body = '';
    request.on('data', (chunk) => { body += chunk; });
    request.on('end', () => {
      const message = JSON.parse(body);
      const answer = handle(message);
      if (!answer) { response.writeHead(202).end(); return; }
      const headers = { 'mcp-session-id': 'fixture-session' };
      if (streaming) {
        response.writeHead(200, { ...headers, 'content-type': 'text/event-stream' });
        response.write(`event: message\ndata: ${JSON.stringify({ jsonrpc: '2.0', method: 'notifications/progress', params: {} })}\n\n`);
        response.end(`event: message\ndata: ${JSON.stringify(answer)}\n\n`);
      } else {
        response.writeHead(200, { ...headers, 'content-type': 'application/json' });
        response.end(JSON.stringify(answer));
      }
    });
  });
  server.listen(0, '127.0.0.1', () => writeFileSync(portFile, String(server.address().port)));
} else {
  let buffer = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => {
    buffer += chunk;
    let newline;
    while ((newline = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0, newline); buffer = buffer.slice(newline + 1);
      if (!line.trim()) continue;
      const answer = handle(JSON.parse(line));
      if (answer) process.stdout.write(`${JSON.stringify(answer)}\n`);
    }
  });
  process.stdin.on('end', () => process.exit(0));
}
